mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM personal_survey
    WHERE member_id = #{memberId}
)

mapper.update:
UPDATE member
SET investment_type = #{investmentType}
WHERE id = #{memberId}
    AND status = 'ACTIVE'
    AND deleted_at IS NULL

UPDATE couple
SET investment_type = #{investmentType}
WHERE id = #{coupleId}
